function normalizeSelection(value) {
    if (!Array.isArray(value)) {
        return [];
    }
    const normalized = [];
    for (const item of value) {
        if (typeof item === 'string') {
            normalized.push(item);
            continue;
        }
        if (typeof item === 'object' && item !== null && 'value' in item) {
            const nestedValue = item.value;
            if (typeof nestedValue === 'string') {
                normalized.push(nestedValue);
            }
        }
    }
    return normalized;
}
function normalizeSingleSelection(value) {
    if (typeof value === 'string') {
        return value;
    }
    if (typeof value === 'object' && value !== null && 'value' in value) {
        const nestedValue = value.value;
        if (typeof nestedValue === 'string') {
            return nestedValue;
        }
    }
    return null;
}
function splitSelectionByState(choices, selectedValues) {
    const selectedSet = new Set(selectedValues);
    const toInstall = [];
    const toRemove = [];
    for (const choice of choices) {
        const isInstalled = choice.checked === true;
        const isSelected = selectedSet.has(choice.value);
        if (isSelected && !isInstalled) {
            toInstall.push(choice.value);
            continue;
        }
        if (!isSelected && isInstalled) {
            toRemove.push(choice.value);
        }
    }
    return { toInstall, toRemove };
}
