// Attempts a batch operation first; on failure, retries items individually.
// This is safe because install/remove operations are idempotent — re-copying
// an already-installed file or re-removing an already-absent file is a no-op.
async function applyCategoryChanges(title, changes, installFn, removeFn) {
    const result = {
        errors: [],
        installed: [],
        removed: [],
    };
    if (changes.toInstall.length > 0) {
        try {
            await installFn(changes.toInstall);
            result.installed.push(...changes.toInstall);
        }
        catch {
            for (const item of changes.toInstall) {
                try {
                    await installFn([item]);
                    result.installed.push(item);
                }
                catch (itemError) {
                    result.errors.push(`${title} install failed for "${item}": ${formatError(itemError)}`);
                }
            }
        }
    }
    if (changes.toRemove.length > 0) {
        try {
            await removeFn(changes.toRemove);
            result.removed.push(...changes.toRemove);
        }
        catch {
